const maximumValue = totalHouseholdMembers < 6 ? calc.hoechstbetrag[totalHouseholdMembers][rentLevel] + calc.klimakomponente[totalHouseholdMembers] : calc.hoechstbetrag[5][rentLevel] + calc.klimakomponente[totalHouseholdMembers] + calc.hoechstbetrag.mehrAlsFuenf[rentLevel] * (totalHouseholdMembers - 5);
      const rent = base.$homeResident.is(':checked') ? maximumValue : base.localizedParseFloat(base.$rent.val());
      const monthlyTotalExpenditure = (rent < maximumValue ? rent : maximumValue) * eligibleHouseholdMembers / totalHouseholdMembers;
      const a = calc.a[eligibleHouseholdMembers];
      const b = calc.b[eligibleHouseholdMembers];
      const c = calc.c[eligibleHouseholdMembers];
      const M = base.max(monthlyTotalExpenditure + calc.heizkostenEntlastung[totalHouseholdMembers] * eligibleHouseholdMembers / totalHouseholdMembers, calc.M[totalHouseholdMembers]);
      const Y = base.max(monthlyTotalIncome, calc.Y[eligibleHouseholdMembers]);
      //Fix rounding
      const massiveNumber = 100000000;
      const z1 = massiveNumber * a + massiveNumber * b * M + massiveNumber * c * Y;
      const z2 = z1 / massiveNumber * Y;
      const z3 = M - z2;
      const z4 = 1.15 * z3;
      const result = Math.round(z4);
      base.$result.val(result < 10 ? 0 : result);

Bei der Ermittlung des Gesamteinkommens sind die folgenden jährlichen Freibeträge abzuziehen: 1. 1 800 Euro für jedes schwerbehinderte zu berücksichtigende Haushaltsmitglied mit einem Grad der Behinderung a) von 100 oder
b) von unter 100 bei Pflegebedürftigkeit im Sinne des § 14 des Elften Buches Sozialgesetzbuch und gleichzeitiger häuslicher oder teilstationärer Pflege oder Kurzzeitpflege;
2. 750 Euro für jedes zu berücksichtigende Haushaltsmitglied, das Opfer der nationalsozialistischen Verfolgung oder ihm im Sinne des Bundesentschädigungsgesetzes gleichgestellt ist;
3. 1 320 Euro, wenn a) ein zu berücksichtigendes Haushaltsmitglied ausschließlich mit einem Kind oder mehreren Kindern Wohnraum gemeinsam bewohnt und
b) mindestens eines dieser Kinder noch nicht 18 Jahre alt ist und für dieses Kindergeld nach dem Einkommensteuergesetz oder dem Bundeskindergeldgesetz oder eine in § 65 Absatz 1 Satz 1 des Einkommensteuergesetzes genannte Leistung gewährt wird;
4. ein Betrag in Höhe der eigenen Einnahmen aus Erwerbstätigkeit jedes Kindes eines Haushaltsmitgliedes, höchstens jedoch 1 200 Euro, wenn das Kind ein zu berücksichtigendes Haushaltsmitglied und noch nicht 25 Jahre alt ist.

